        struct SyncPtr(*mut c_void);
        unsafe impl Sync for SyncPtr {}

        static VALUE: SyncPtr = SyncPtr(&VALUE.0 as *const *mut c_void as *mut c_void);

        extern "C-unwind" fn check_value(value: *mut c_void) {
